# RW4DM_SESSION: ClearUndo: the undo memory. The script rw4dm_session_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_SESSION_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_SESSION_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_session_script.txt" 2>&1)" || { echo "$RW4_SESSION_OUT" | tail -40; echo "FAIL RW4DM_SESSION_run: script exited non-zero"; fail=1; RW4_SESSION_OUT=""; }
else
  RW4_SESSION_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_session_script.txt" 2>&1)" || { echo "$RW4_SESSION_OUT" | tail -40; echo "FAIL RW4DM_SESSION_run: script exited non-zero"; fail=1; RW4_SESSION_OUT=""; }
fi
rw4_session_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_SESSION_OUT"; }
# rw4_session_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_session_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_session_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_SESSION_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_SESSION_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_session_state undo_works "1:point:Default" "before ClearUndo, Undo takes a Move back: the point is at (1,0,0) again" "  1,0,0$"
rw4_session_state redo "1:point:Default" "Redo brings the Move back: the point is at (6,0,0)" "  6,0,0$"
rw4_session_state clearundo "1:point:Default" "ClearUndo empties the undo memory: Undo and Redo then find nothing, and the model is untouched (the point stays at (6,0,0))" "Undo history cleared" "Nothing to undo" "Nothing to redo" "  6,0,0$"
